package net.officefloor.hq.app.claim;

/**
 * A claim's status. It starts as DRAFT, is opened (OPEN) and then settled (SETTLED). A clerk's
 * settle above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). SETTLED and VOID
 * are final. Only OPEN, PENDING and SETTLED claims count toward any total.
 */
public enum ClaimStatus {
    DRAFT(null), OPEN("CLAIM_OPENED"), PENDING("CLAIM_PENDING"), SETTLED("CLAIM_SETTLED"), VOID("CLAIM_VOIDED");

    private final String auditEvent;

    ClaimStatus(String auditEvent) {
        this.auditEvent = auditEvent;
    }

    /** The audit event written when a claim moves into this status. */
    public String auditEvent() {
        return auditEvent;
    }

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/**
 * Records the claim's new status; a settled claim's line ends with the due it was settled at (n/a
 * when its grade had no rate).
 * Runs after every rule has passed, so a refused change writes nothing.
 */
public class AuditClaimStatus {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(line(sheet, claim, Audit.user(request), people));
    }

    /** The claim's status line as the given user changed it. */
    static String line(Sheet sheet, Claim claim, String user, PersonRepository people) {
        String line = ClaimAudit.line(claim.getStatus().auditEvent(), sheet, user,
                people.find(sheet.id(), claim.getPersonId()), claim);
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        return line;
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the approval; the line ends with the due it was settled at (n/a when its grade had no rate). */
public class AuditClaimApproved {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_APPROVED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim)
                + " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString()));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the re-settle, naming the claim; the line ends with its old and new due (n/a for none). */
public class AuditClaimResettled {
    public void audit(@Val Sheet sheet, @Val Claim claim, @Val Resettlement resettlement, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_RESETTLED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim)
                + " old=" + shown(resettlement.old()) + " new=" + shown(resettlement.now()));
    }

    private static String shown(BigDecimal due) {
        return due == null ? "n/a" : due.toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * A claim's audit record: its person, its amount as the screen shows it, its date, and its number
 * when it has one (a voided claim keeps the number it had).
 */
final class ClaimAudit {
    private ClaimAudit() {}

    static String line(String event, Sheet sheet, String user, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + sheet.id() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber());
    }
}
# Edit a claim's amount, date and note. Validate first so a bad amount or date is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim dated inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaim
  govern: [ transaction ]
  next: correction
# A correction (a negative amount) must name a settled claim of the same person: else a 400.
correction:
  class: net.officefloor.hq.app.claim.CheckCorrection
  govern: [ transaction ]
  next: closedTo
# Nor may an edit move it into one.
closedTo:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: retired
# Nor may an edit date it after its person's retirement date.
retired:
  class: net.officefloor.hq.app.person.CheckClaimRetired
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimEdited
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Settle the selected claims together, in list order, by the rules of settling one. Each that
# cannot be settled is refused and left as it is; the response tells how many were settled (a claim
# sent to PENDING counts) and how many refused.
validate:
  class: net.officefloor.hq.app.claim.ValidateBulkSettle
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: settle
# Each claim settled is audited as it is settled: its own line, then the figures it moved.
settle:
  class: net.officefloor.hq.app.claim.SettleSelectedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
  govern: [ transaction ]

