/**
 * Notifies the watchers of a claim's person that it was settled (approved, re-settled): one line per
 * watcher, in the order they started watching. Runs after the claim's own line, before the rollup
 * lines; a claim not SETTLED (sent to PENDING) notifies no one.
 */
public class NotifyWatchers {
    public void notify(@Val Sheet sheet, @Val Claim claim, PersonRepository people, WatchRepository watches,
            HttpServletRequest request, Audit audit) {
        lines(sheet, claim, Audit.user(request), people, watches).forEach(audit::record);
    }

    /** The notify lines for the claim as the given user changed it. */
    public static List<String> lines(Sheet sheet, Claim claim, String user, PersonRepository people,
            WatchRepository watches) {
        if (claim.getStatus() != ClaimStatus.SETTLED) return List.of();
        String name = people.find(sheet.id(), claim.getPersonId()).getName();
        return watches.watchers(sheet.id(), claim.getPersonId()).stream()
                .map((w) -> "NOTIFY sheet=" + sheet.id() + " by=" + user + " user=" + w + " person=" + name
                        + " number=" + claim.getNumber())
                .toList();
    }
}
